// === src/errors.js ===
export class AppError extends Error {
  constructor(status, message) { super(message); this.status = status; }
}
// === src/repositories/produk.repository.js ===
const data = [{ id: 1, nama: 'Kopi Susu', stok: 3 }];
export const produkRepo = {
  cari: (id) => data.find((p) => p.id === id) ?? null,
  simpan: (p) => { Object.assign(data.find((x) => x.id === p.id), p); return p; },
};
// === src/services/produk.service.js ===
import { produkRepo } from '../repositories/produk.repository.js';
import { AppError } from '../errors.js';
export function kurangiStok(id, jumlah) {
  const p = produkRepo.cari(id);
  if (!p) throw new AppError(404, 'Produk tidak ada');
  if (p.stok < jumlah) throw new AppError(409, `Stok ${p.nama} tinggal ${p.stok}`);
  return produkRepo.simpan({ ...p, stok: p.stok - jumlah });
}
// === src/controllers/produk.controller.js ===
import * as produkService from '../services/produk.service.js';
export function beli(req, res) {
  const hasil = produkService.kurangiStok(Number(req.params.id), req.body.jumlah);
  res.json(hasil);
}
// === src/app.js ===
