import express from 'express';
const produk = [{ id: 1, nama: 'Kopi', harga: 18000 }];
const app = express();
app.use(express.json());
app.patch('/produk/:id/harga', (req, res) => {
  const p = produk.find((x) => x.id === Number(req.params.id));
  if (!p) return res.status(404).json({ error: 'Produk tidak ada' });
  if (req.body.harga <= 0) return res.status(400).json({ error: 'Harga harus positif' });
  p.harga = req.body.harga;
  res.json(p);
});
const server = app.listen(3000);
const r = await fetch('http://localhost:3000/produk/1/harga', { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ harga: 20000 }) });
console.log(r.status, await r.json());
server.close();

